cd /app/categorizationapp/categorizationapp && python3 - <<'PY'
import difflib,re
def norm(l): return re.sub(r'\s+','',l)
a=open('BankScripts/Axis.py').read().splitlines()
b=open('BankScripts/Indusind.py').read().splitlines()
sm=difflib.SequenceMatcher(None,[norm(x) for x in a],[norm(x) for x in b])
for tag,i1,i2,j1,j2 in sm.get_opcodes():
    if tag=='replace' and (i2-i1)<=3 and (j2-j1)<=3:
        # show near matches
        for x in range(i1,i2):
            for y in range(j1,j2):
                r=difflib.SequenceMatcher(None,norm(a[x]),norm(b[y])).ratio()
                if r>0.85:
                    print(f"--- ratio {r:.3f}\nAxis:{x+1}: {a[x].strip()}\nIndu:{y+1}: {b[y].strip()}\n")
PY
